  "content_type": "legal_ruling",
  "chunks": [
    {
      "chunk_type": "opening",
      "arabic_text": "إِذَا تَرَكَ الْمَيِّتُ عَمّاً فَالْمَالُ كُلُّهُ لِلْعَمِّ",
      "translations": {
        "en": "If the deceased leaves behind a paternal uncle, then all the wealth belongs to the paternal uncle."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ كَذَلِكَ إِنْ تَرَكَ عَمَّيْنِ أَوْ ثَلَاثَةَ أَعْمَامٍ أَوْ أَكْثَرَ فَالْمَالُ بَيْنَهُمْ بِالسَّوِيَّةِ",
      "translations": {
        "en": "Likewise, if he leaves two paternal uncles, or three or more paternal uncles, the wealth is divided equally among them."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ أَعْمَاماً وَ عَمَّاتٍ فَالْمَالُ كُلُّهُ بَيْنَهُمْ‌ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ",
      "translations": {
        "en": "If he leaves behind paternal uncles and paternal aunts, the entire wealth is divided among them with the male receiving the share of two females."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ عَمَّيْنِ أَحَدَهُمَا لِأَبٍ وَ أُمٍّ وَ الْآخَرَ لِلْأَبِ فَالْمَالُ لِلْعَمِّ مِنَ الْأَبِ وَ الْأُمِّ وَ سَقَطَ الْعَمُّ لِلْأَبِ",
      "translations": {
        "en": "If he leaves two paternal uncles, one being from both father and mother, and the other from the father only, the wealth belongs to the paternal uncle from both father and mother, and the paternal uncle from the father alone is excluded."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ عَمّاً لِأَبٍ وَ أُمٍّ وَ عَمّاً لِأُمٍّ فَلِلْعَمِّ مِنَ الْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِلْعَمِّ لِلْأَبِ وَ الْأُمِّ",
      "translations": {
        "en": "If he leaves a paternal uncle from both father and mother and a paternal uncle from the mother, then the paternal uncle from the mother receives one-sixth, and the remainder belongs to the paternal uncle from both father and mother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ كَذَلِكَ إِنْ تَرَكَ عَمَّةً لِأَبٍ وَ عَمَّةً لِأُمٍّ فَلِلْعَمَّةِ مِنَ الْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِلْعَمَّةِ مِنَ الْأَبِ",
      "translations": {
        "en": "Similarly, if he leaves a paternal aunt from the father and a paternal aunt from the mother, then the paternal aunt from the mother receives one-sixth, and the remainder goes to the paternal aunt from the father."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ خَالاً فَالْمَالُ كُلُّهُ لِلْخَالِ وَ كَذَلِكَ إِنْ تَرَكَ خَالَيْنِ أَوْ ثَلَاثَةً أَوْ أَكْثَرَ فَالْمَالُ بَيْنَهُمْ بِالسَّوِيَّةِ",
      "translations": {
        "en": "If he leaves behind a maternal uncle, all the wealth belongs to the maternal uncle. Similarly, if he leaves behind two or more maternal uncles, the wealth is divided equally among them."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ أَخْوَالاً وَ خَالاتٍ فَالْمَالُ بَيْنَهُمْ بِالسَّوِيَّةِ الذَّكَرُ وَ الْأُنْثَى فِيهِ سَوَاءٌ",
      "translations": {
        "en": "If he leaves maternal uncles and maternal aunts, the wealth is divided equally among them, with males and females receiving equal shares."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ خَالَيْنِ أَحَدُهُمَا لِأَبٍ وَ أُمٍّ وَ الْآخَرُ لِلْأَبِ فَالْمَالُ لِلْخَالِ مِنَ الْأَبِ وَ الْأُمِّ وَ سَقَطَ الْخَالُ لِلْأَبِ",
      "translations": {
        "en": "If he leaves two maternal uncles, one from both father and mother, and the other from the father only, the wealth goes to the maternal uncle from both father and mother, and the maternal uncle from the father alone is excluded."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ خَالَيْنِ أَحَدُهُمَا لِأُمٍّ وَ الْآخَرُ لِأَبٍ وَ أُمٍّ فَلِلْخَالِ مِنَ الْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِلْخَالِ لِلْأَبِ وَ الْأُمِّ",
      "translations": {
        "en": "If he leaves two maternal uncles, one from the mother and the other from both father and mother, the maternal uncle from the mother receives one-sixth, and the remainder belongs to the maternal uncle from both father and mother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ كَذَلِكَ إِنْ تَرَكَ خَالاً لِأَبٍ وَ خَالاً لِأُمٍّ فَلِلْخَالِ مِنَ الْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِلْخَالِ مِنَ الْأَبِ",
      "translations": {
        "en": "Similarly, if he leaves a maternal uncle from the father and a maternal uncle from the mother, the maternal uncle from the mother receives one-sixth, and the remainder goes to the maternal uncle from the father."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ كَذَلِكَ إِنْ تَرَكَ خَالَةً لِأُمٍّ وَ خَالَةً لِأَبٍ فَلِلْخَالَةِ مِنَ الْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِلْخَالَةِ مِنَ الْأَبِ",
      "translations": {
        "en": "Likewise, if he leaves a maternal aunt from the mother and a maternal aunt from the father, the maternal aunt from the mother receives one-sixth, and the remainder belongs to the maternal aunt from the father."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ ثَلَاثَةَ أَخْوَالٍ مُتَفَرِّقِينَ وَ ثَلَاثَةَ أَعْمَامٍ مُتَفَرِّقِينَ فَلِلْخَالَيْنِ الثُّلُثُ",
      "translations": {
        "en": "If he leaves behind three separate maternal uncles and three separate paternal uncles, one-third of the wealth goes to the maternal uncles."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "لِلْخَالِ مِنَ الْأُمِّ السُّدُسُ مِنَ الثُّلُثِ وَ لِلْخَالِ لِلْأَبِ وَ الْأُمِّ خَمْسَةُ أَسْدَاسِ الثُّلُثِ وَ سَقَطَ الْخَالُ مِنَ الْأَبِ",
      "translations": {
        "en": "One-sixth of that third goes to the maternal uncle from the mother and five-sixths go to the maternal uncle from both father and mother, and the maternal uncle from the father is excluded."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ لِلْعَمَّيْنِ الثُّلُثَانِ لِلْعَمِّ مِنَ الْأُمِّ السُّدُسُ مِنَ الثُّلُثَيْنِ وَ لِلْعَمِّ مِنَ الْأَبِ وَ الْأُمِّ خَمْسَةُ أَسْدَاسِ الثُّلُثَيْنِ وَ سَقَطَ الْعَمُّ لِلْأَبِ",
      "translations": {
        "en": "Two-thirds of the wealth go to the paternal uncles, with one-sixth of those two-thirds going to the paternal uncle from the mother and five-sixths going to the paternal uncle from both father and mother, and the paternal uncle from the father is excluded."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ حِسَابُهُ مِنْ سِتَّةٍ وَ ثَلَاثِينَ‌ لِلْخَالِ مِنَ الْأُمِّ مِنْ ذَلِكَ سَهْمَانِ وَ لِلْخَالِ لِلْأَبِ وَ الْأُمِّ عَشَرَةُ أَسْهُمٍ وَ لِلْعَمِّ مِنَ الْأُمِّ مِنْ ذَلِكَ أَرْبَعَةُ أَسْهُمٍ وَ لِلْعَمِّ مِنَ الْأَبِ وَ الْأُمِّ عِشْرُونَ سَهْماً",
      "translations": {
        "en": "The calculation is based on thirty-six parts, with two parts for the maternal uncle from the mother, ten parts for the maternal uncle from both father and mother, four parts for the paternal uncle from the mother, and twenty parts for the paternal uncle from both father and mother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ خَالَيْنِ لِأَبٍ وَ أُمٍّ وَ خَالَيْنِ لِأُمٍّ وَ عَمَّيْنِ لِأَبٍ وَ أُمٍّ وَ عَمَّيْنِ مِنَ الْأُمِّ فَلِلْخَالَيْنِ مِنَ الْأُمِّ ثُلُثُ الثُّلُثِ أَرْبَعَةٌ مِنْ سِتَّةٍ وَ ثَلَاثِينَ",
      "translations": {
        "en": "If he leaves two maternal uncles from both father and mother and two maternal uncles from the mother, then the two maternal uncles from the mother receive one-third of the third, amounting to four out of thirty-six."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ لِلْخَالَيْنِ مِنَ الْأَبِ وَ الْأُمِّ ثُلُثَا الثُّلُثِ ثَمَانِيَةٌ مِنْ سِتَّةٍ وَ ثَلَاثِينَ",
      "translations": {
        "en": "And the two maternal uncles from both father and mother receive two-thirds of the third, amounting to eight out of thirty-six."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ لِلْعَمَّيْنِ مِنَ الْأُمِّ ثُلُثُ الثُّلُثَيْنِ ثَمَانِيَةٌ مِنْ سِتَّةٍ وَ ثَلَاثِينَ",
      "translations": {
        "en": "The two paternal uncles from the mother receive one-third of the two-thirds, amounting to eight out of thirty-six."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ لِلْعَمَّيْنِ مِنَ الْأَبِ وَ الْأُمِّ سِتَّةَ عَشَرَ مِنْ سِتَّةٍ وَ ثَلَاثِينَ",
      "translations": {
        "en": "And the two paternal uncles from both father and mother receive sixteen out of thirty-six."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ أَخْوَالاً وَ خَالاتٍ وَ أَعْمَاماً وَ عَمَّاتٍ فَلِلْأَخْوَالِ وَ الْخَالاتِ الثُّلُثُ بَيْنَهُمْ بِالسَّوِيَّةِ الذَّكَرُ وَ الْأُنْثَى فِيهِ سَوَاءٌ",
      "translations": {
        "en": "If he leaves maternal uncles, maternal aunts, paternal uncles, and paternal aunts, then one-third of the wealth goes equally to the maternal uncles and maternal aunts, with males and females sharing equally."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ لِلْأَعْمَامِ وَ الْعَمَّاتِ الثُّلُثَانِ‌ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ",
      "translations": {
        "en": "And two-thirds go to the paternal uncles and paternal aunts, with males receiving twice the share of females."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ خَالاً لِأَبٍ وَ عَمّاً لِأُمٍّ فَلِلْخَالِ مِنَ الْأَبِ الثُّلُثُ وَ لِلْعَمِّ لِلْأُمِّ الثُّلُثَانِ",
      "translations": {
        "en": "If he leaves a maternal uncle from the father and a paternal uncle from the mother, then one-third of the wealth goes to the maternal uncle from the father, and two-thirds go to the paternal uncle from the mother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ خَالاً لِأُمٍّ وَ عَمّاً لِأَبٍ فَلِلْخَالِ لِلْأُمِّ الثُّلُثُ لِأَنَّهُ لَيْسَ أَحَدٌ مِنْ قِبَلِ الْأُمِّ يُشَارِكُهُ فِي الْمِيرَاثِ‌ وَ لِلْعَمِّ مِنَ الْأَبِ الثُّلُثَانِ",
      "translations": {
        "en": "If he leaves a maternal uncle from the mother and a paternal uncle from the father, then one-third goes to the maternal uncle from the mother because no one from the maternal side competes with him in inheritance, and two-thirds go to the paternal uncle from the father."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ عَمّاً لِأَبٍ وَ ابْنَ عَمٍّ لِأَبٍ وَ أُمٍّ فَالْمَالُ لِابْنِ الْعَمِّ لِلْأَبِ وَ الْأُمِّ لِأَنَّهُ قَدْ جَمَعَ الْكَلَالَتَيْنِ كَلَالَةَ الْأَبِ وَ كَلَالَةَ الْأُمِّ",
      "translations": {
        "en": "If he leaves a paternal uncle from the father and a cousin from both father and mother, then the wealth belongs to the cousin from both father and mother because he combines both paternal and maternal ties."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ هَذَا غَيْرُ مَحْمُولٍ عَلَى أَصْلٍ‌ بَلْ مُسَلَّمٌ لِلْخَبَرِ الصَّحِيحِ الْوَارِدِ عَنِ الْأَئِمَّةِ ع",
      "translations": {
        "en": "This is not based on analogy but is confirmed by authentic narrations from the Imams (peace be upon them)."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ ابْنَيْ عَمٍّ أَحَدُهُمَا أَخٌ لِأُمٍّ فَالْمَالُ لِلْأَخِ مِنَ الْأُمِّ",
      "translations": {
        "en": "If he leaves two paternal cousins, one being a maternal brother, the wealth belongs to the maternal brother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَتِ امْرَأَةٌ ابْنَيْ عَمٍّ أَحَدُهُمَا زَوْجٌ فَلِلزَّوْجِ النِّصْفُ وَ النِّصْفُ الْآخَرُ بَيْنَهُمَا نِصْفَانِ",
      "translations": {
        "en": "If a woman leaves behind two paternal cousins, one being her husband, the husband receives half, and the remaining half is divided equally between the cousins."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ الرَّجُلُ ابْنَةَ عَمٍّ لِأَبٍ وَ أُمٍّ وَ ابْنَةَ عَمٍّ لِأُمٍّ فَلِابْنَةِ الْعَمِّ مِنَ الْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِابْنَةِ الْعَمِّ لِلْأَبِ وَ الْأُمِّ",
      "translations": {
        "en": "If a man leaves behind a paternal cousin from both father and mother and a paternal cousin from the mother, then the paternal cousin from the mother receives one-sixth, and the remainder goes to the paternal cousin from both father and mother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ كَذَلِكَ إِذَا تَرَكَ ابْنَ خَالٍ لِأَبٍ وَ أُمٍّ وَ ابْنَ خَالٍ لِأُمٍّ فَلِابْنَةِ الْخَالِ لِلْأُمِّ السُّدُسُ وَ مَا بَقِيَ فَلِابْنَةِ الْخَالِ لِلْأَبِ وَ الْأُمِّ",
      "translations": {
        "en": "Similarly, if he leaves a maternal uncle from both father and mother and a maternal uncle from the mother, then the daughter of the maternal uncle from the mother receives one-sixth, and the remainder goes to the daughter of the maternal uncle from both the father and the mother."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ إِنْ تَرَكَ خَالاً وَ جَدَّةً لِأُمٍّ فَالْمَالُ لِجَدَّةِ الْأُمِّ وَ سَقَطَ الْخَالُ",
      "translations": {
        "en": "If he leaves a maternal uncle and a maternal grandmother, the wealth belongs to the maternal grandmother, and the maternal uncle is excluded."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ غَلِطَ الْفَضْلُ بْنُ شَاذَانَ فِي قَوْلِهِ الْمَالُ بَيْنَهُمَا نِصْفَانِ بِمَنْزِلَةِ ابْنِ الْأَخِ وَ الْجَدِّ",
      "translations": {
        "en": "Al-Fadl ibn Shadhan was mistaken in saying the wealth is divided equally between them, similar to the division between the son of the brother and the grandfather."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ إِنْ تَرَكَ عَمّاً وَ ابْنَ أُخْتٍ فَالْمَالُ لِابْنِ الْأُخْتِ",
      "translations": {
        "en": "If he leaves a paternal uncle and a nephew (son of his sister), the wealth belongs to the nephew."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "فَإِنْ تَرَكَ عَمّاً وَ ابْنَ أَخٍ فَالْمَالُ لِابْنِ الْأَخِ",
      "translations": {
        "en": "If he leaves a paternal uncle and a nephew (son of his brother), the wealth belongs to the nephew."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "وَ غَلِطَ يُونُسَ بْنُ عَبْدِ الرَّحْمَنِ فِي قَوْلِهِ الْمَالُ بَيْنَهُمَا نِصْفَانِ‌",
      "translations": {
        "en": "Yunus ibn Abd Al-Rahman was mistaken in saying the wealth is divided equally between them."
      }
    },
